INSERT INTO faculty (id, email, password_hash, full_name, username, designation, department, institution, phone, office_location, office_hours, visiting_hours, address, bio, photo, resume_file, website, google_scholar, linkedin, is_detached, detached_at, github, research_summary, is_active, created_at) VALUES ('2', 'sunita.reddy@university.edu', 'scrypt:32768:8:1$1B72hahQx2ObFxDC$07d648c120b036461b893d79fc30c308e6873c9b46f805bea8bde62c16c40ea1aa014e66f5b1bbb60a00a363d6c7a0331940191699ec60f9dd9cc6e4a4453beb', 'Dr. Sunita Reddy', 'sunita', 'Professor', 'Electronics and Communication Engineering', 'National Institute of Technology', '+91-9876543211', 'Block B, Room 210', 'Tue-Thu, 11:00 AM - 1:00 PM', 'Mon-Fri, 3:00 PM - 5:00 PM', 'Department of ECE, NIT Campus, Jaipur, Rajasthan - 302017', 'Dr. Sunita Reddy is a Professor in the Department of Electronics and Communication Engineering at NIT Jaipur. She earned her Ph.D. from IISc Bangalore in 2010 and has over 15 years of academic experience. Her research areas include VLSI design, embedded systems, IoT, and signal processing. She has authored 2 textbooks, holds 3 patents, and has published over 60 research papers. She has received the Best Paper Award at IEEE INDICON 2022 and serves on the editorial board of the Journal of Signal Processing Systems.', '', '', 'https://sunitareddy.nitj.ac.in', 'https://scholar.google.com/citations?user=sunitareddy', 'https://linkedin.com/in/sunitareddy', '1', '2026-08-24 19:03:34', '', 'VLSI Design, Embedded Systems, Internet of Things, Digital Signal Processing', '1', '2026-08-24 19:00:26');
INSERT INTO qualifications (id, faculty_id, degree, specialization, university, year_of_passing, certificate_photo, is_published) VALUES ('4', '2', 'Ph.D. Electronics and Communication', 'VLSI Design', 'Indian Institute of Science Bangalore', '2010', 'phd_sunita.svg', '1');
INSERT INTO qualifications (id, faculty_id, degree, specialization, university, year_of_passing, certificate_photo, is_published) VALUES ('5', '2', 'M.Tech VLSI Systems', 'VLSI Design', 'National Institute of Technology Trichy', '2006', '', '1');
INSERT INTO qualifications (id, faculty_id, degree, specialization, university, year_of_passing, certificate_photo, is_published) VALUES ('6', '2', 'B.E. Electronics and Communication', 'Electronics', 'Visvesvaraya Technological University', '2004', '', '1');
INSERT INTO research_interests (id, faculty_id, title, description, is_published) VALUES ('5', '2', 'VLSI Design and Verification', 'Low-power VLSI circuit design, hardware description languages, and formal verification techniques for complex digital systems.', '1');
INSERT INTO research_interests (id, faculty_id, title, description, is_published) VALUES ('6', '2', 'Internet of Things', 'IoT system architecture, sensor networks, edge computing, and smart infrastructure development.', '1');
INSERT INTO research_interests (id, faculty_id, title, description, is_published) VALUES ('7', '2', 'Digital Signal Processing', 'Audio and image signal processing, adaptive filtering, and real-time DSP system implementation on FPGAs.', '1');
INSERT INTO research_interests (id, faculty_id, title, description, is_published) VALUES ('8', '2', 'Embedded Systems', 'Real-time operating systems, ARM architecture, and embedded system design for industrial applications.', '1');
INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('7', '2', 'IEEE INDICON 2022 Best Paper Award', 'Best paper award for "Low-Power FPGA Implementation of Adaptive Signal Processing Algorithms" at IEEE INDICON.', 'award', '2022', 'best_paper_sunita.svg', '1');
INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('8', '2', 'INAE Young Engineer Award', 'Indian National Academy of Engineering award for contributions to VLSI design methodology.', 'award', '2018', '', '1');
INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('9', '2', 'Patent - Smart Sensor Array', 'Granted Indian patent for "Array-based sensor system for real-time environmental monitoring" (IN202141056789).', 'patent', '2021', '', '1');
INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('10', '2', 'Patent - Low-Power Memory Controller', 'Patent granted for "Energy-efficient memory controller for IoT devices" (IN202041023456).', 'patent', '2020', '', '1');
INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('11', '2', 'DST-Women Scientist Award', 'Recognized for research contributions in embedded systems for healthcare applications.', 'award', '2019', '', '1');
INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('12', '2', 'Editorial Board - Journal of Signal Processing Systems', 'Appointed to the editorial board of the Springer Journal of Signal Processing Systems.', 'recognition', '2023', 'ieee_fellow.svg', '1');
INSERT INTO publications (id, faculty_id, title, authors, journal, year, doi, url, abstract, pub_type, is_published) VALUES ('5', '2', 'Low-Power FPGA Implementation of Adaptive Signal Processing Algorithms', 'S. Reddy, K. Raman, A. Nair', 'IEEE INDICON Proceedings', '2022', '10.1109/indicon.2022.98765', 'https://doi.org/10.1109/indicon.2022.98765', 'This paper presents an optimized FPGA implementation of LMS-based adaptive filtering algorithms targeting low-power IoT applications. Our implementation achieves 40% power reduction compared to existing solutions while maintaining signal processing accuracy.', 'conference', '1');
INSERT INTO publications (id, faculty_id, title, authors, journal, year, doi, url, abstract, pub_type, is_published) VALUES ('6', '2', 'Energy-Efficient Memory Architecture for IoT Edge Devices', 'S. Reddy, P. Menon', 'IEEE Transactions on VLSI Systems', '2021', '10.1109/tvlsi.2021.56789', 'https://doi.org/10.1109/tvlsi.2021.56789', 'We propose a novel memory architecture that reduces static power consumption in IoT edge devices by 35% through intelligent power gating and adaptive refresh scheduling. The architecture is validated on a 28nm test chip.', 'journal', '1');
INSERT INTO publications (id, faculty_id, title, authors, journal, year, doi, url, abstract, pub_type, is_published) VALUES ('7', '2', 'IoT-Based Smart Healthcare Monitoring System: A Comprehensive Survey', 'S. Reddy, R. Das, M. Joshi', 'ACM Computing Surveys', '2020', '10.1145/3456789', 'https://doi.org/10.1145/3456789', 'A comprehensive survey of IoT-based healthcare monitoring systems covering sensor technologies, communication protocols, data processing frameworks, and privacy considerations. We analyze 40 recent systems and propose a reference architecture.', 'journal', '1');
INSERT INTO courses (id, faculty_id, name, code, description, semester, schedule, is_published) VALUES ('4', '2', 'VLSI Design', 'EC401', 'CMOS circuit design, logic synthesis, physical design, timing analysis, and FPGA-based prototyping. Hands-on projects using Cadence and Xilinx tools.', 'Odd Semester 2024-25', 'Mon-Wed 11:00 AM-12:30 PM', '1');
INSERT INTO courses (id, faculty_id, name, code, description, semester, schedule, is_published) VALUES ('5', '2', 'Digital Signal Processing', 'EC301', 'Discrete-time signals and systems, Z-transform, DFT, FFT, FIR and IIR filter design, and practical DSP implementation.', 'Even Semester 2024-25', 'Tue-Thu 10:00-11:30 AM', '1');
INSERT INTO courses (id, faculty_id, name, code, description, semester, schedule, is_published) VALUES ('6', '2', 'Embedded Systems', 'EC501', 'ARM Cortex-M architecture, RTOS concepts, interrupt handling, peripheral interfacing, and real-time system design with FreeRTOS.', 'Odd Semester 2024-25', 'Mon-Fri 2:00-3:00 PM', '1');
INSERT INTO students (id, faculty_id, name, program, research_topic, status, start_year, email, is_published) VALUES ('6', '2', 'Deepak Nair', 'Ph.D.', 'Low-Power IoT Circuit Design', 'ongoing', '2021', 'deepak.nair@nitj.ac.in', '1');
