INSERT INTO projects (id, faculty_id, title, description, funding_agency, amount, status, start_year, end_year, is_published) VALUES ('4', '2', 'Smart Agriculture IoT Platform', 'Designing an IoT-based precision agriculture system with soil sensors, weather stations, and automated irrigation control using LoRaWAN connectivity.', 'DST-Agri', '32,00,000', 'ongoing', '2023', '', '1');
INSERT INTO projects (id, faculty_id, title, description, funding_agency, amount, status, start_year, end_year, is_published) VALUES ('5', '2', 'Low-Power Wearable Health Monitor', 'Developing a wearable health monitoring device with ECG, SpO2, and temperature sensors using ultra-low-power microcontrollers.', 'DBT', '20,00,000', 'ongoing', '2022', '', '1');
INSERT INTO projects (id, faculty_id, title, description, funding_agency, amount, status, start_year, end_year, is_published) VALUES ('6', '2', 'FPGA Signal Processing Library', 'An open-source library of optimized signal processing IP cores for Xilinx and Intel FPGAs.', 'MeitY', '8,00,000', 'completed', '2019', '2022', '1');
INSERT INTO announcements (id, faculty_id, title, content, is_important, is_published, created_at) VALUES ('4', '2', 'VLSI Design Lab - New Equipment', 'The VLSI Design Lab has received new Xilinx Artix-7 FPGA boards for student projects. Slots are available for final year projects - contact me during office hours.', '1', '1', '2026-08-24 19:00:26');
INSERT INTO announcements (id, faculty_id, title, content, is_important, is_published, created_at) VALUES ('5', '2', 'Workshop on Embedded Systems with FreeRTOS', 'A 3-day hands-on workshop on embedded systems development with FreeRTOS will be held from October 5-7, 2024. Registration is open to all ECE students.', '0', '1', '2026-08-24 19:00:26');
INSERT INTO announcements (id, faculty_id, title, content, is_important, is_published, created_at) VALUES ('6', '2', 'PhD Openings - IoT and Signal Processing', 'Looking for motivated Ph.D. students in IoT systems and signal processing. Minimum qualification: GATE score above 600 or equivalent. Send your CV to my email.', '1', '1', '2026-08-24 19:00:26');
